#include "cf_noise_tone.h"
#include "cf_math.h"
#include <limits.h>
static uint16_t r16(const uint8_t*p){return(uint16_t)p[0]|(uint16_t)((uint16_t)p[1]<<8);}static uint32_t r32(const uint8_t*p){return(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}static void w16(uint8_t*p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);}static void w32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}static int16_t s16(uint16_t u){return(u&0x8000u)?(int16_t)(-1-(int16_t)(uint16_t)~u):(int16_t)u;}static int32_t s32(uint32_t u){return(u&0x80000000u)?-1-(int32_t)~u:(int32_t)u;}static uint32_t u32(int32_t s){return s>=0?(uint32_t)s:~(uint32_t)(-1-s);}static int32_t asr(int32_t v,unsigned n){uint32_t b;if(!n)return v;b=u32(v)>>n;if(v<0)b|=(~0u)<<(32u-n);return s32(b);}static int32_t mullo(int32_t a,int32_t b){return s32(pk_cf_mul_lo_u32(u32(a),u32(b)));}static int16_t clamp16(int32_t v){if(v>INT16_MAX)return INT16_MAX;if(v<INT16_MIN)return INT16_MIN;return(int16_t)v;}
static uint16_t linenv(uint8_t*s,size_t b){uint8_t st=s[b];int32_t v=s32(r32(s+b+0xc));switch(st){case 0:if(s[b+7]||s[b+4])s[b]=1;break;case 1:v=s32(u32(v)+(uint32_t)r16(s+b+0x20));w32(s+b+0xc,u32(v));if(s[b+4]){if(v>0xffffe){s[b]=4;if(v>=0x100000){v=0xfffff;w32(s+b+0xc,u32(v));}}}else if(v>0xffffe){s[b]=s[b+6]?4:3;if(v>=0x100000){v=0xfffff;w32(s+b+0xc,u32(v));}}break;case 2:break;case 3:if(!s[b+7]&&(s[b+4]||!s[b+0x10]))s[b]=4;break;case 4:if(s[b+7])s[b]=1;else{v=s32(u32(v)-(uint32_t)r16(s+b+0x22));w32(s+b+0xc,u32(v));if(v<=0){v=0;w32(s+b+0xc,0);s[b]=s[b+4]?1:0;}}break;default:break;}return(uint16_t)((u32(v)>>4)&0xffffu);}
static int16_t m1sample(const uint8_t*t,uint32_t i){return s16(r16(t+(size_t)(i&0x7ffu)*2u));}static int m1osc(uint8_t*s,const uint8_t*a,uint32_t aa,const uint8_t*b,uint32_t ba,int16_t*out){const size_t base=0xd4;uint32_t ph=r32(s+base+4)+r32(s+base+8),cur;const uint8_t*t;uint32_t lp,po,i,j;int32_t f,x,y;w32(s+base+4,ph);cur=r32(s+base+0x10);if(s32(ph)>0x100000){uint32_t nx=r32(s+base+0x14);ph-=0x100000;w32(s+base+4,ph);if(nx!=cur){cur=nx;w32(s+base+0x10,cur);}}if(cur==aa)t=a;else if(cur==ba)t=b;else return 0;lp=ph;po=r32(s+base+0xc);if(po){lp+=po;if(s32(lp)>0x100000)lp-=0x100000;}i=(lp>>9)&0x7ffu;j=(i+1)&0x7ffu;f=(int32_t)(lp&0x1ffu);x=(int32_t)m1sample(t,i);y=(int32_t)m1sample(t,j);*out=s16((uint16_t)(x+asr(mullo(y-x,f),9)));return 1;}
int pk_cf_nt_m1_render(uint8_t*s,int16_t*d,uint32_t n,const uint8_t*a,uint32_t aa,const uint8_t*b,uint32_t ba){uint32_t i;if(!s||!d||!a||!b||s[0x75]!=0)return 0;for(i=0;i<n;i++){uint16_t e=linenv(s,0x74);uint32_t ph=r32(s+0xd8),red=r32(s+0xc8);int16_t o=0;int32_t x;if(ph>red)w32(s+0xd8,ph-red);if(!m1osc(s,a,aa,b,ba,&o))return 0;if(s[0xb8]){d[i]=0;continue;}x=asr(mullo((int32_t)o,(int32_t)e),17);x=asr(mullo(x,(int32_t)s[6]),8);d[i]=clamp16(x);}return 1;}
static uint16_t tab16(const uint8_t*t,size_t i){return r16(t+i*2u);}static int16_t tabs16(const uint8_t*t,size_t i){return s16(tab16(t,i));}static const uint8_t*findwave(const pk_cf_nt_shared_tables*t,uint32_t a){unsigned i;for(i=0;i<4;i++)if(t->waves[i].table&&t->waves[i].address==a)return t->waves[i].table;return 0;}
static uint16_t env(uint8_t*s,size_t b,const pk_cf_nt_shared_tables*t){uint8_t st=s[b];int32_t v=s32(r32(s+b+0xc));switch(st){case 0:if(s[b+7]||s[b+4])s[b]=1;break;case 1:v=s32(u32(v)+(uint32_t)r16(s+b+0x20));w32(s+b+0xc,u32(v));if(s[b+4]){if(v>0xffffe){s[b]=4;if(v>=0x100000){v=0xfffff;w32(s+b+0xc,u32(v));}}}else if(v>0xffffe){s[b]=s[b+6]?4:3;if(v>=0x100000){v=0xfffff;w32(s+b+0xc,u32(v));}}break;case 2:break;case 3:if(!s[b+7]&&(s[b+4]||!s[b+0x10]))s[b]=4;break;case 4:if(s[b+7])s[b]=1;else{v=s32(u32(v)-(uint32_t)r16(s+b+0x22));w32(s+b+0xc,u32(v));if(v<=0){v=0;w32(s+b+0xc,0);s[b]=s[b+4]?1:0;}}break;default:break;}if(s[b+1]!=1&&s[b+1]!=2)return(uint16_t)((u32(v)>>4)&0xffffu);{const uint8_t*c=s[b+1]==1?t->envelope1:t->envelope2;uint32_t raw,idx,nx;int32_t f,a,z;if(!c)return 0;raw=u32(v);idx=(raw>>10)&0x7ffu;nx=(idx+1)&0x7ffu;f=(int32_t)(raw&0x3ffu);a=(int32_t)tab16(c,idx);z=(int32_t)tab16(c,nx);return(uint16_t)(a+asr(mullo(z-a,f),10));}}
static uint32_t rnd(pk_cf_nt_rng*r){const uint32_t a=0x5851f42d,b=0x4c957f2d;uint32_t ol=r->low,oh=r->high,acc=pk_cf_mul_lo_u32(ol,a),pl=pk_cf_mul_lo_u32(ol,b),ph=pk_cf_mul_hi_u32(ol,b),nl=pl+1u,carry=nl<pl,nh;acc+=pk_cf_mul_lo_u32(oh,b);nh=acc+ph+carry;r->low=nl;r->high=nh;return nh&0x7fffffffu;}static int16_t noise(uint8_t*s,size_t b,pk_cf_nt_rng*r){uint16_t c=r16(s+b);int16_t x;if(c){w16(s+b,(uint16_t)(c-1));return s16(r16(s+b+0x10));}w16(s+b,r16(s+b+2));x=s16((uint16_t)rnd(r));w16(s+b+0x10,(uint16_t)x);return x;}
static void filt(uint8_t*s,size_t b,int32_t input){uint16_t coeff=r16(s+b+0xe);int32_t velocity=s32(r32(s+b+0x18)),p=mullo(velocity,(int32_t)coeff),first,second,fb;if(p<0)p=s32(u32(p)+0xffffu);first=s32(r32(s+b+0x10));first=s32(u32(first)+u32(asr(p,16)));if(first>32767)first=32767;else if(first<-32767)first=-32767;w32(s+b+0x10,u32(first));second=s32(u32(input)-u32(first));p=mullo(velocity,(int32_t)r16(s+b+0xc));second=s32(u32(second)-u32(asr(p,10)));if(second>32767)second=32767;else if(second<-32767)second=-32767;w32(s+b+0x14,u32(second));fb=mullo(second,(int32_t)coeff);if(fb<0)fb=s32(u32(fb)+0xffffu);velocity=s32(u32(velocity)+u32(asr(fb,16)));if(velocity>32767)velocity=32767;else if(velocity<-32767)velocity=-32767;w32(s+b+0x18,u32(velocity));}
static int oscs(uint8_t*s,size_t b,const pk_cf_nt_shared_tables*t,int16_t*out){uint32_t ph=r32(s+b+4)+r32(s+b+8),cur;const uint8_t*tb;uint32_t i,j;int32_t f,a,z;w32(s+b+4,ph);cur=r32(s+b+0xc);if(s32(ph)>0x100000){uint32_t nx=r32(s+b+0x10);ph-=0x100000;w32(s+b+4,ph);if(nx!=cur){cur=nx;w32(s+b+0xc,cur);}}tb=findwave(t,cur);if(!tb)return 0;i=(ph>>12)&0xffu;j=(i+1)&0xffu;f=(int32_t)(ph&0xfffu);a=(int32_t)tabs16(tb,i);z=(int32_t)tabs16(tb,j);*out=s16((uint16_t)(a+asr(mullo(z-a,f),12)));return 1;}
int pk_cf_nt_shared_render(uint8_t*s,int16_t*d,uint32_t n,const pk_cf_nt_shared_tables*t,pk_cf_nt_rng*r){uint32_t i;if(!s||!d||!t||!r)return 0;for(i=0;i<n;i++){uint16_t amp=env(s,0x74,t);int32_t nz=(int32_t)noise(s,0x60,r);uint32_t mixu=r32(s+0xf8);int32_t mix=s32(mixu),acc,sum,tonal,out;int16_t o1=0,o2=0;filt(s,0x9c,nz);filt(s,0x9c,nz);acc=asr(mullo(mix,nz),13);if(!oscs(s,0x2c,t,&o1)||!oscs(s,0xc4,t,&o2))return 0;sum=asr(s32((uint32_t)((int32_t)o1+(int32_t)o2)),4);tonal=mullo(s32(0x00000fffu-mixu),sum);acc=s32(u32(acc)+u32(asr(tonal,9)));out=asr(mullo(acc,(int32_t)amp),16);out=asr(mullo(out,(int32_t)s[6]),8);d[i]=clamp16(out);}return 1;}
